'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():'p'+Date.now().toString(36)+Math.random().toString(36).slice(2);
const STORE='math-growth-v1', cn=['一','二','三','四','五','六'], roman=['','Ⅰ','Ⅱ','Ⅲ'];
let trainGrade=0;
let D, state, selected, activeView='map', block=-1, cap=-1, zoom=1, activeTrain=null, modalMode='', persistOK=true;
const abilities=[
['按明确标准分类、发现规律','自选标准，区分表象与结构','提炼共同结构，用反例检查范围'],
['从实例提取数量、性质与关系','用符号表达共同关系','建立一般表达，讨论条件与边界'],
['在文字、算式与图形间对应','主动换表示帮助理解','构造表示，揭示隐藏关系'],
['根据条件作直接推理','连接多步条件，说明依据','组织推理链，检查遗漏与边界'],
['借助提示转成已学问题','自主拆分、组合或代换','连续转化解决陌生综合问题'],
['识别整体和相等关系','把复杂部分作为整体替换','构造整体，联合多个关系推演'],
['找到可用的已学知识','比较不同题目的共同方法','跨知识点、跨板块组合解决'],
['检查计算、单位和合理性','换一种方法验证并定位错误','用反例、极端情况检验结论']];
const profile=()=>state.profiles.find(p=>p.id===state.active), node=id=>D.nodes.find(n=>n.id===id), rec=id=>profile().records[id]||(profile().records[id]={tiers:{},seen:false}), stage=id=>{const r=profile().records[id];let s=0;while(s<3&&r?.tiers[s]?.passed)s++;return s;};
function save(){try{localStorage.setItem(STORE,JSON.stringify(state));persistOK=true;}catch(e){persistOK=false;toast('当前设备无法保存，请导出备份后再退出。');}}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').style.display='none',3300);}
function loadState(){try{state=JSON.parse(localStorage.getItem(STORE));}catch(e){} if(!validState(state)){const id=uid();state={version:1,active:id,profiles:[{id,name:'我的学习档案',records:{},history:[]}]};}save();}
function validState(s){
 if(!s||s.version!==1||!Array.isArray(s.profiles)||!s.profiles.length||s.profiles.length>30||!s.profiles.some(p=>p.id===s.active))return false;
 const object=x=>x&&typeof x==='object'&&!Array.isArray(x);
 return new Set(s.profiles.map(p=>p.id)).size===s.profiles.length&&s.profiles.every(p=>typeof p.id==='string'&&typeof p.name==='string'&&p.name.length<=40&&object(p.records)&&Array.isArray(p.history)&&Object.entries(p.records).every(([id,r])=>/^k\d+$/.test(id)&&D.nodes.some(n=>n.id===id)&&object(r)&&object(r.tiers)&&Object.entries(r.tiers).every(([t,tr])=>['0','1','2'].includes(t)&&object(tr)&&object(tr.answers)&&Object.entries(tr.answers).every(([i,a])=>/^[0-5]$/.test(i)&&object(a)&&(a.text===undefined||typeof a.text==='string')))));
}
function due(id){const r=profile().records[id];if(!stage(id)||!r?.passedAt)return false;return Date.now()-r.passedAt>3*86400000&&(!r.delay?.passed||!r.delay?.eligible||r.delay.at<r.passedAt);}
function filtered(){const g=+$('#grade').value,t=+$('#term').value,q=$('#search').value.trim().toLowerCase();return D.nodes.filter(n=>(!g||n.grade===g)&&(!t||n.term===t)&&(block<0||n.block===block)&&(cap<0||n.caps.includes(cap))&&(!q||(n.name+n.desc).toLowerCase().includes(q)));}
function init(){loadState();selected=D.nodes.find(n=>n.name==='乘法分配律').id;$('#loading').hidden=true;$('#app').hidden=false;for(let i=1;i<=6;i++)$('#grade').add(new Option(cn[i-1]+'年级',i));$('#blockFilters').innerHTML=D.blocks.map((b,i)=>`<button class="blockbtn" data-block="${i}"><i class="dot"></i>${E(b)}<small>${D.nodes.filter(n=>n.block===i).length}</small></button>`).join('');
$('#blockFilters').addEventListener('click',e=>{const b=e.target.closest('[data-block]');if(b){block=block===+b.dataset.block?-1:+b.dataset.block;renderMap();}});$('#allBlocks').onclick=()=>{block=-1;cap=-1;$('#grade').value='0';$('#term').value='0';$('#search').value='';renderMap();};$('#grade').onchange=$('#term').onchange=()=>renderMap();$('#search').oninput=()=>renderMap();
$$('nav [data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('#profileBtn').onclick=profilesModal;$('#aboutBtn').onclick=$('#footerAbout').onclick=aboutModal;$('#expandMap').onclick=()=>{const card=$('.mapcard');const open=card.classList.toggle('expanded');$('#expandMap').textContent=open?'收起画布':'展开画布';document.body.classList.toggle('body-lock',open);if(open){setZoom(Math.min(1,($('#mapScroller').clientWidth-20)/1170));}requestAnimationFrame(drawLinks);};$('#modalClose').onclick=closeModal;$('#modal').addEventListener('cancel',()=>{activeTrain=null;modalMode='';document.body.classList.remove('body-lock');refresh();});$('#closeDetail').onclick=()=>$('#detail').classList.remove('open');$('#showLines').onchange=drawLinks;$('#zoomIn').onclick=()=>setZoom(zoom+.15);$('#zoomOut').onclick=()=>setZoom(zoom-.15);$('#fitMap').onclick=()=>{const sc=$('#mapScroller'), grid=$('#mapGrid');setZoom(Math.min((sc.clientWidth-20)/1170,(sc.clientHeight-20)/grid.scrollHeight));sc.scrollTop=sc.scrollLeft=0;toast('已展开全部可见年级；点“＋”可放大阅读。');};$('#starter').onclick=()=>{setView('map');selectNode(D.nodes.find(n=>n.name==='乘法分配律').id,true);};
$('#mapGrid').onclick=e=>{const b=e.target.closest('[data-node]');if(b)selectNode(b.dataset.node);};window.addEventListener('resize',()=>requestAnimationFrame(drawLinks));
renderTree();renderAbility();refresh();renderDetail();
}
function refresh(){ $('#profileName').textContent=profile().name;renderStats();renderMap();renderTraining();renderProgress();if(selected)renderDetail(); }
function setView(v){activeView=v;$$('.view').forEach(s=>s.hidden=s.id!==v+'View');$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));if(v==='map')requestAnimationFrame(drawLinks);if(v==='progress')renderProgress();$('#detail').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'});}
function renderStats(){const started=Object.values(profile().records).filter(r=>Object.keys(r.tiers||{}).length).length,passed=D.nodes.filter(n=>stage(n.id)>0).length;$('#stats').innerHTML=`<div class="stat"><strong>${D.nodes.length}<em>个</em></strong><span>全小学主要知识节点</span></div><div class="stat"><strong>6<em>个年级</em></strong><span>12个上下学期层级</span></div><div class="stat"><strong>${D.edges.length}</strong><span>带理由的知识联系</span></div><div class="stat"><strong>${passed}<em>/ ${started}</em></strong><span>已通过 / 已开始诊断</span></div>`;}
function renderTree(){ $('#tree').innerHTML=cn.map((c,i)=>`<details><summary>${c}年级 <span class="smallnote">${D.nodes.filter(n=>n.grade===i+1).length}个节点</span></summary>${[1,2].map(t=>`<div class="treeterm">${t===1?'上':'下'}学期 · 参考位置</div>${D.nodes.filter(n=>n.grade===i+1&&n.term===t).map(n=>`<button class="treeitem" data-id="${n.id}">${E(n.name)}</button>`).join('')}`).join('')}</details>`).join('');$('#tree').onclick=e=>{const b=e.target.closest('[data-id]');if(b)reveal(b.dataset.id);}; }
function mapClass(n){let s=stage(n.id),r=profile().records[n.id];return s?'stage'+s:r&&Object.keys(r.tiers||{}).length?'inprogress':'';}
function renderMap(){const ns=filtered(), present=new Set(ns.map(n=>n.id));$$('.blockbtn').forEach(b=>b.classList.toggle('active',+b.dataset.block===block));$('#shownCount').textContent=`显示 ${ns.length} / ${D.nodes.length} 节点 · ${cap>=0?D.capnames[cap]+'训练方向':'点节点查看依据'}`;let h=`<div class="mapcol">年级</div>${D.blocks.map(b=>`<div class="mapcol">${E(b)}</div>`).join('')}`;for(let g=1;g<=6;g++){if(+$('#grade').value&&g!==+$('#grade').value)continue;for(let t=1;t<=2;t++){if(+$('#term').value&&t!==+$('#term').value)continue;h+=`<div class="gradecell" id="grade-${g}-${t}"><span>${cn[g-1]}年级<small>${t===1?'上':'下'}学期<br>参考年级</small></span></div>`;for(let b=0;b<5;b++){let cell=ns.filter(n=>n.grade===g&&n.term===t&&n.block===b);h+=`<div class="mapcell">${cell.length?cell.map(n=>`<button class="node ${mapClass(n)} ${n.id===selected?'selected':''} ${due(n.id)?'review':''}" data-node="${n.id}" id="node-${n.id}" aria-label="${E(n.name)}，${cn[g-1]}年级${t===1?'上':'下'}学期参考位置，${stage(n.id)?roman[stage(n.id)]+'阶自检通过':'尚未通过诊断'}"><i class="pin"></i><span class="nm">${E(n.name)}</span><span class="badge">${roman[stage(n.id)]|| (D.banks[n.id]?'◇':'')}</span></button>`).join(''):'<span class="emptycell">—</span>'}</div>`;}}}$('#mapGrid').innerHTML=h;setZoom(zoom);renderJump();highlightNodes();requestAnimationFrame(drawLinks);}
function renderJump(){let bar=$('#gradeJump');if(!bar){bar=document.createElement('div');bar.id='gradeJump';bar.className='actions';bar.style.cssText='padding:8px 12px;border-bottom:1px solid #e4ebf1;background:#fbfdff';$('#mapScroller').before(bar);}bar.innerHTML=cn.map((c,i)=>`<button data-jump="${i+1}" style="padding:4px 9px;font-size:10px">${c}年级</button>`).join('');bar.onclick=e=>{const b=e.target.closest('[data-jump]');if(!b)return;const g=+b.dataset.jump;if(+$('#grade').value&&+$('#grade').value!==g){$('#grade').value='0';renderMap();}const target=$(`#grade-${g}-${+$('#term').value||1}`);if(target){if(zoom<.6)setZoom(.8);$('#mapScroller').scrollTop=target.offsetTop*zoom;}};}
function setZoom(z){zoom=Math.min(1.6,Math.max(.15,z));$('#mapCanvas').style.zoom=zoom;$('#zoomLabel').textContent=Math.round(zoom*100)+'%';requestAnimationFrame(drawLinks);}
function highlightNodes(){const related=new Set(D.edges.filter(e=>e.source===selected||e.target===selected).flatMap(e=>[e.source,e.target]));$$('.node').forEach(el=>{el.classList.toggle('related',el.dataset.node!==selected&&related.has(el.dataset.node));el.classList.toggle('selected',el.dataset.node===selected);});}
function drawLinks(){if(activeView!=='map')return;const svg=$('#links'),canvas=$('#mapCanvas'),grid=$('#mapGrid');svg.setAttribute('width',1170);svg.setAttribute('height',grid.scrollHeight);let all=$('#showLines').checked;let s='<defs><marker id="arrow" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0 0 L6 3 L0 6" fill="none" stroke="#739ab6" stroke-width="1"/></marker></defs>';const cb=canvas.getBoundingClientRect();D.edges.filter(e=>all||e.source===selected||e.target===selected).forEach(e=>{const a=$('#node-'+e.source),b=$('#node-'+e.target);if(!a||!b)return;const ar=a.getBoundingClientRect(),br=b.getBoundingClientRect(),x1=(ar.right-cb.left)/zoom-2,y1=(ar.top+ar.height/2-cb.top)/zoom,x2=(br.left-cb.left)/zoom+2,y2=(br.top+br.height/2-cb.top)/zoom;let path;if(Math.abs(x2-x1)<250&&Math.abs(y2-y1)>45){const off= Math.max(x1,x2)+23;path=`M${x1} ${y1} C${off+38} ${y1},${off+38} ${y2},${x2} ${y2}`;}else{const mid=(x1+x2)/2;path=`M${x1} ${y1} C${mid} ${y1},${mid} ${y2},${x2} ${y2}`;}const dash=e.kind==='必要'?'':e.kind==='促进'?'6 5':'2 5';s+=`<path d="${path}" fill="none" stroke="${e.kind==='必要'?'#3b6c8e':'#91afc5'}" stroke-width="${all?'1':'1.5'}" opacity="${all?'.24':'.85'}" stroke-dasharray="${dash}" marker-end="url(#arrow)"/>`;});svg.innerHTML=s;}
function reveal(id){$('#grade').value='0';$('#term').value='0';$('#search').value='';block=-1;cap=-1;setView('map');renderMap();selectNode(id,true);}
function selectNode(id,scroll=false){selected=id;const r=rec(id);r.seen=true;save();renderDetail();highlightNodes();drawLinks();$('#detail').classList.add('open');if(scroll){if(zoom<.5)setZoom(.8);requestAnimationFrame(()=>{const el=$('#node-'+id);if(el){$('#mapScroller').scrollTop=Math.max(0,el.offsetTop*zoom-160);$('#mapScroller').scrollLeft=Math.max(0,el.offsetLeft*zoom-100);}});}}
function edgeCard(e,incoming){const n=node(incoming?e.source:e.target);return `<div class="rel ${e.kind==='必要'?'necessary':''}"><span class="tag">${E(e.kind==='必要'?'任务限定 · 必要':e.kind==='促进'?'条件性促进':e.kind)}</span><button data-link="${n.id}">${incoming?'←':'→'} ${E(n.name)}</button><small>${cn[n.grade-1]}年级${n.term===1?'上':'下'} · 参考位置</small><details><summary>为什么连接？</summary><p><b>目标任务：</b>${E(e.task)}</p><p>${E(e.reason)}</p><small>${E(e.status)}；不自动作为学习门槛。</small></details></div>`;}
function renderDetail(){if(!selected)return;const n=node(selected),r=profile().records[n.id],incoming=D.edges.filter(e=>e.target===n.id),out=D.edges.filter(e=>e.source===n.id),bank=D.banks[n.id];$('#detailBody').innerHTML=`<div class="detailcontent"><div class="breadcrumb">${E(D.blocks[n.block])} / ${cn[n.grade-1]}年级${n.term===1?'上':'下'}学期</div><h2>${E(n.name)}</h2><span class="tag">年级、册次待核对</span><span class="tag">${bank?'三阶诊断已配置':'训练待补充'}</span><p class="explanation">${E(n.desc)}</p><div class="stair">${D.tiers.map((t,i)=>`<span class="${stage(n.id)>i?'done':''}">${roman[i+1]}<br>${t.slice(0,2)}${t.slice(-2)}</span>`).join('')}</div>${bank?`<button class="primary" id="detailTrain">${stage(n.id)?'继续检查 / 复习':'开始多维诊断'} ↗</button><p class="smallnote">每阶6项任务，可随时暂停。开放题对照要点自检，提示完成另记。</p>${due(n.id)?'<p class="smallnote due">◌ 已到建议复查时间，可以用新题检查是否仍会。</p>':''}`:'<div class="notice">这个知识点在完整图谱中。三阶任务正在补充，尚未形成诊断证据。</div>'}<p class="smallnote">${r?.seen?'已浏览':'未浏览'} ≠ 已掌握。${stage(n.id)?'目前通过：'+roman[stage(n.id)]+'阶（客观题判定＋开放题自检）。':''}</p><div class="sectiontitle">检查前面的基础 <span class="smallnote">${incoming.length}条</span></div>${incoming.length?incoming.map(e=>edgeCard(e,true)).join(''):'<p class="smallnote">当前未录入前向关系，不代表不需要基础。可先从实物、图示或生活经验进入。</p>'}<div class="sectiontitle">它还能通向哪里 <span class="smallnote">${out.length}条</span></div>${out.length?out.map(e=>edgeCard(e,false)).join(''):'<p class="smallnote">后续联系仍在扩充。</p>'}<div class="sectiontitle">可以练哪些能力</div><div class="capchips">${n.caps.map(c=>`<button data-cap="${c}">${E(D.capnames[c])}</button>`).join('')}</div><p class="smallnote">${bank?'按本节点实际任务关联。':'这些是候选训练方向，待具体任务验证。'}节点阶梯不能直接代表整项能力的等级。</p><div class="sectiontitle">卡住时，可以这样做</div><p class="smallnote">读条件 → 找关系 → 换表达 → 选方法 → 连知识 → 检验。先确定哪一步卡住，再检查有关基础；不要求把全部前置内容重学一遍。</p></div>`;$('#detailBody').onclick=e=>{const l=e.target.closest('[data-link]'),c=e.target.closest('[data-cap]');if(l)reveal(l.dataset.link);if(c){cap=+c.dataset.cap;setView('ability');$('#abilityFilterMsg').textContent='当前关注：'+D.capnames[cap]+'。可点“在知识地图中寻找”查看各年级相关节点。';}if(e.target.closest('#detailTrain'))openTraining(n.id);};}
function renderAbility(){const holder=$('#abilityMatrix');holder.innerHTML='<div id="abilityFilterMsg" class="notice">各阶描述用于设计任务，不是标准化分数。一个孩子在不同情境中可以表现不同。</div><div class="abilitywrap"><div class="abilitymatrix"><div class="th">能力模块</div>'+D.tiers.map((t,i)=>`<div class="th">${roman[i+1]} ${t}</div>`).join('')+D.capnames.map((c,i)=>`<div class="abilityname">${E(c)}<button data-capmap="${i}">在知识地图中寻找 ↗</button></div>${abilities[i].map((a,t)=>`<div class="cell"><p>${E(a)}</p><button data-captrain="${i}" data-tier="${t}">查看相关任务</button></div>`).join('')}`).join('')+'</div></div>';holder.onclick=e=>{const a=e.target.closest('[data-capmap]'),b=e.target.closest('[data-captrain]');if(a){cap=+a.dataset.capmap;block=-1;$('#grade').value='0';$('#search').value='';setView('map');renderMap();toast('已显示该能力的候选知识节点，关系仍需具体任务验证。');}if(b){const c=+b.dataset.captrain,t=+b.dataset.tier;const ids=Object.keys(D.banks).filter(id=>D.banks[id].tiers[t].some(q=>q.cap===c));showModal(D.capnames[c]+' · '+roman[t+1]+'阶任务',ids.length?ids.map(id=>`<div class="record"><b>${E(node(id).name)}</b><p>${D.banks[id].tiers[t].filter(q=>q.cap===c).map(q=>E(q.prompt)).join('<br>')}</p><button data-bank="${id}" data-t="${t}">进入本阶任务</button></div>`).join(''):'<p>这一能力在该阶的专门任务待补充。可以先查看知识图谱中的候选方向。</p>');$$('[data-bank]').forEach(el=>el.onclick=()=>openTraining(el.dataset.bank,+el.dataset.t));}};}
function renderTraining(){const entries=Object.keys(D.banks).filter(id=>!trainGrade||node(id).grade===trainGrade).sort((a,b)=>node(a).block-node(b).block);$('#trainingCards').innerHTML='<div style="grid-column:1/-1"><label>选择参考年级 <select id="trainGrade" aria-label="训练参考年级"><option value="0">全部年级</option>'+cn.map((c,i)=>'<option value="'+(i+1)+'" '+(trainGrade===i+1?'selected':'')+'>'+c+'年级</option>').join('')+'</select></label><p class="smallnote">各年级均已配有训练节点；年级仅为参考，按已掌握基础选择挑战。</p></div>'+entries.map((id,i)=>{const n=node(id);return `<article class="trainingcard"><span class="num">0${i+1}</span><div class="eyebrow">${E(D.blocks[n.block])} · ${cn[n.grade-1]}年级参考任务</div><h3>${E(n.name)}</h3><p>概念与条件 / 操作与表示 / 结构与推理 / 迁移与检验</p><div class="stair">${D.tiers.map((t,j)=>`<span class="${stage(id)>j?'done':''}">${roman[j+1]} ${j===0?'理解应用':j===1?'变式识别':'迁移推理'}</span>`).join('')}</div><button data-start="${id}">开始 / 继续诊断 ↗</button> <button class="textbutton" data-map="${id}">在图谱中查看</button></article>`;}).join('');$('#trainGrade').onchange=e=>{trainGrade=+e.target.value;renderTraining();};$('#trainingCards').onclick=e=>{const b=e.target.closest('[data-start]'),m=e.target.closest('[data-map]');if(b)openTraining(b.dataset.start);if(m)reveal(m.dataset.map);};}
function showModal(title,html){$('#modalBody').onclick=null;$('#modalBody').oninput=null;$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();document.body.classList.add('body-lock');$('#modalBody').scrollTop=0;}
function closeModal(){activeTrain=null;modalMode='';$('#modal').close();document.body.classList.remove('body-lock');refresh();}
function tierRecord(id,t){const r=rec(id);r.tiers??={};r.tiers[t]??={answers:{},passed:false};return r.tiers[t];}
function questionHTML(q,i,a={}){const v=E(a.text||'');return `<div class="question" data-question="${i}"><div class="label">${String(i+1).padStart(2,'0')} / ${E(q.dim)} · ${E(D.capnames[q.cap])}</div><h3>${E(q.prompt)}</h3>${q.expected?`<label class="smallnote" for="ans-${i}">填写数值（单位见题干；题目要求解释时可写在草稿里）</label><input id="ans-${i}" data-answer="${i}" type="text" inputmode="decimal" placeholder="你的答案" value="${v}">`:`<label class="smallnote" for="ans-${i}">写下想法；也可先画在纸上，再用文字说明。</label><textarea id="ans-${i}" data-answer="${i}" placeholder="我看到的关系是……">${v}</textarea>`}<button class="textbutton" data-hint="${i}">${a.hint?'提示已使用':'需要一点提示'}</button>${a.hint?`<div class="notice">${E(q.hint)}</div>`:''}<div><button class="evalbtn" data-check="${i}">${q.expected?'检查答案与要点':'展开对照要点并自检'}</button></div>${a.revealed?`<div class="rubric"><b>对照要点</b><br>${E(q.answer)}${q.expected?`<div class="qresult ${a.correct?'':'wrong'}">${a.correct?'数值答案正确。':'数值答案暂不符合，保留这次记录，先检查关系与计算。'} ${a.hint?'已使用提示，后续需换题独立复查。':''}</div>`:`<p class="smallnote">先独立写出思路，再对照检查。这里是自检记录，不是AI对解释的自动评分。</p><div class="ratings"><button data-rating="0" data-i="${i}" class="${a.rating===0?'chosen':''}">还没有想清楚</button><button data-rating="1" data-i="${i}" class="${a.rating===1?'chosen':''}">看要点 / 提示后会</button><button data-rating="2" data-i="${i}" class="${a.rating===2?'chosen':''}">原来思路已包含要点</button></div>`}</div>`:''}</div>`;}
function taskSet(id,t){const tr=tierRecord(id,t);return tr.round===1?D.banks[id].alternate[t]:D.banks[id].tiers[t];}
function openTraining(id,t){modalMode='training';const bank=D.banks[id];if(!bank)return;const current=stage(id);t=t??Math.min(current,2);activeTrain={id,t};const tr=tierRecord(id,t);save();showModal(node(id).name+' · 三阶多维诊断',`<div class="tiernav">${D.tiers.map((name,i)=>`<button data-tiernav="${i}" class="${i===t?'active':''}">${roman[i+1]} ${i===0?'理解应用':i===1?'变式识别':'迁移推理'}${stage(id)>i?' ✓':''}</button>`).join('')}</div><div class="notice">${tr.round===1?'正在做第二组独立复查题。':'正在做首轮诊断题。'}本阶6项任务，不计时。${t>current?'你正在预览更高一阶；可以探索，地图通过状态仍按连续阶梯累计。':'先做能做的部分；需要时使用提示。'}<br>通过条件：6项均独立完成，开放题对照要点自检。提示后完成保留记录，换题复查后再推进。</div>${taskSet(id,t).map((q,i)=>questionHTML(q,i,tr.answers[i])).join('')}<div class="actions"><button id="lessonBtn">先补一个小环节</button>${tr.round!==1?'<button id="newRound">换一组题独立检查</button>':''}</div><div class="savebar"><small>回答自动暂存于当前档案${persistOK?'':'；保存不可用，请导出'}</small><button id="pauseTraining">暂停，稍后继续</button><button id="finishTier" class="primary">保存本阶结果</button></div>`);attachTraining();}
function attachTraining(){const {id,t}=activeTrain,questions=taskSet(id,t),tr=tierRecord(id,t);$('#modalBody').oninput=e=>{if(e.target.dataset.answer!==undefined){const i=+e.target.dataset.answer;tr.answers[i]??={};const a=tr.answers[i];a.text=e.target.value;if(a.revealed&&questions[i].expected){a.correct=false;a.afterReview=true;}if(a.revealed&&!questions[i].expected){a.rating=undefined;a.afterReview=true;}tr.passed=false;save();}};$('#modalBody').onclick=e=>{const nav=e.target.closest('[data-tiernav]'),hint=e.target.closest('[data-hint]'),check=e.target.closest('[data-check]'),rating=e.target.closest('[data-rating]');if(nav){openTraining(id,+nav.dataset.tiernav);return;}if(hint){const i=+hint.dataset.hint;tr.answers[i]??={};tr.answers[i].hint=true;tr.passed=false;save();rerenderQuestion(i);return;}if(check){const i=+check.dataset.check;tr.answers[i]??={};const a=tr.answers[i];if(!a.text?.trim()){toast('先写下你的尝试，再看要点。');return;}if(!a.revealed)a.original=a.text;a.revealed=true;if(questions[i].expected)a.correct=questions[i].expected.includes(normalize(a.text));save();rerenderQuestion(i);return;}if(rating){const i=+rating.dataset.i;tr.answers[i]??={};tr.answers[i].rating=+rating.dataset.rating;save();rerenderQuestion(i);return;}if(e.target.closest('#pauseTraining')){save();closeModal();toast('已保存，下次可以接着做。');}if(e.target.closest('#lessonBtn'))lessonModal(id,t);if(e.target.closest('#newRound')){const r=rec(id);r.archive??=[];r.archive.push({t,record:JSON.parse(JSON.stringify(tr)),at:Date.now()});r.tiers[t]={answers:{},passed:false,round:1};save();openTraining(id,t);toast('原尝试已归档，新题从独立尝试开始。');}if(e.target.closest('#finishTier'))finishTier(id,t);};}
function normalize(s){return s.trim().replace(/[０-９]/g,c=>String.fromCharCode(c.charCodeAt(0)-65248)).replace(/[,，\s]/g,'').replace(/^(\d+)\.0+$/,'$1');}
function rerenderQuestion(i){const {id,t}=activeTrain,q=taskSet(id,t)[i],a=tierRecord(id,t).answers[i],el=$(`[data-question="${i}"]`);const wrapper=document.createElement('div');wrapper.innerHTML=questionHTML(q,i,a);el.replaceWith(wrapper.firstElementChild);}
function taskIndependent(q,a){return !!a&&!a.hint&&!a.afterReview&&!!a.text?.trim()&&(q.expected?a.correct===true:a.rating===2);}
function finishTier(id,t){const tr=tierRecord(id,t),qs=taskSet(id,t);const completed=qs.filter((q,i)=>tr.answers[i]?.revealed&&(q.expected||tr.answers[i].rating!==undefined)).length;const independent=qs.filter((q,i)=>taskIndependent(q,tr.answers[i])).length;tr.passed=independent===6;tr.finishedAt=Date.now();const r=rec(id);if(tr.passed)r.passedAt=Date.now();r.seen=true;const evidence={at:Date.now(),id,t,completed,independent,source:'客观题判定＋开放题自检'};profile().history.push(evidence);save();closeModal();renderDetail();feedbackModal(id,t);toast(tr.passed?roman[t+1]+'阶自检通过。保留证据，3天后可以用新题复查。':`已记录：${completed}/6项检查，${independent}/6项独立完成。可先补缺口，再继续。`);}
function renderProgress(){const rs=profile().records,started=Object.keys(rs).filter(id=>Object.keys(rs[id].tiers||{}).length),passed=started.filter(id=>stage(id)>0);let h=`<div class="statbar"><div class="stat"><strong>${started.length}</strong><span>已开始诊断节点</span></div><div class="stat"><strong>${passed.length}</strong><span>至少通过第一阶</span></div><div class="stat"><strong>${profile().history.length}</strong><span>保存的任务组记录</span></div></div><p class="smallnote">档案：${E(profile().name)}。证据来自数值题判定与开放题自检；每个节点的结果只对应已做任务。三天后会提示复查。</p>`;
if(!started.length)h+='<div class="empty-state"><h3>每一步，都可以留下证据。</h3><p>先选一个熟悉的知识点，记录你能独立完成什么。这里不设排名。</p><button id="goTraining" class="primary">选择一个训练节点 ↗</button></div>';
for(const id of started){const n=node(id),r=rs[id],s=stage(id);h+=`<div class="record"><b>${E(n.name)}</b> <span class="tag">${s?roman[s]+'阶 · 自检通过':'进行中'}</span><small>${Object.entries(r.tiers||{}).map(([t,tr])=>roman[+t+1]+'阶：'+Object.keys(tr.answers||{}).length+'/6项已开始').join('　')}</small><div class="meter"><span style="width:${s/3*100}%"></span></div><p class="smallnote">${due(id)?'◌ 建议用新题复查。':'已保留原来的尝试、提示使用与自检记录。'}</p><button data-continue="${id}">继续诊断</button> <button data-delay="${id}">独立复查新题</button> <button data-evidence="${id}" class="textbutton">查看任务证据</button></div>`;}
const counts=D.capnames.map((c,i)=>{const rows=[];for(const id of started)for(const [t,tr] of Object.entries(rs[id].tiers||{}))for(const [j,a] of Object.entries(tr.answers||{})){const q=(tr.round===1?D.banks[id]?.alternate[t]:D.banks[id]?.tiers[t])?.[j];if(q?.cap===i&&a.revealed)rows.push({q,a});}return{c,total:rows.length,ind:rows.filter(x=>taskIndependent(x.q,x.a)).length};});h+='<h2 style="margin-top:28px">能力表现：看证据，不贴标签</h2>'+counts.filter(x=>x.total).map(x=>`<div class="record">${E(x.c)}<small>已检查 ${x.total} 项任务，其中 ${x.ind} 项记录为独立完成。尚未据此推断跨情境的能力等级。</small></div>`).join('')+'<div class="below-note"><b>慢一点，不着急。</b><p>提示后会，也是一种进步。补好一个小环节、换一种表示、隔几天仍能做出来，都值得记录。</p></div><div class="actions"><button id="progressBackup">导出与管理档案</button></div>';
$('#progressBody').innerHTML=h;$('#progressBody').onclick=e=>{const b=e.target.closest('[data-continue]'),d=e.target.closest('[data-delay]'),v=e.target.closest('[data-evidence]');if(b)openTraining(b.dataset.continue);if(d)delayModal(d.dataset.delay);if(v)evidenceModal(v.dataset.evidence);if(e.target.closest('#goTraining'))setView('training');if(e.target.closest('#progressBackup'))profilesModal();};}
function evidenceModal(id){const r=rec(id);showModal(node(id).name+' · 学习证据',Object.entries(r.tiers||{}).map(([t,tr])=>`<h3>${roman[+t+1]}阶 ${E(D.tiers[t])}</h3>${Object.entries(tr.answers||{}).map(([i,a])=>{const q=(tr.round===1?D.banks[id]?.alternate[t]:D.banks[id]?.tiers[t])?.[i];return q?`<div class="record"><b>${E(q.prompt)}</b><p>原始尝试：${E(a.original||a.text)}</p>${a.original&&a.original!==a.text?`<p>修改后：${E(a.text)}</p>`:''}<small>${a.hint?'使用过提示':'未使用提示'} / ${q.expected?(a.correct?'数值判定正确':'尚未数值判定通过'):(a.rating===2?'对照要点自检符合':a.rating===1?'看要点后理解':'待自检')} / ${a.afterReview?'看答案后有修改，需新题复查':''}</small></div>`:'';}).join('')}`).join('')||'<p>暂时没有任务记录。</p>');}
function delayModal(id){const r=rec(id),q=D.banks[id].delay,prior=r.delay;showModal(node(id).name+' · 延迟复查',`<div class="notice">请先不看原题和提示完成新题。这次复查只增加一条保留与迁移证据，不会自动补齐未通过的六项任务。${prior?'<br>本节点的新题已使用过，再做属于重复练习，不追加独立延迟证据。':''}</div><h3>${E(q.prompt)}</h3><textarea id="delayAnswer" style="width:100%;min-height:100px;padding:12px" placeholder="写出答案与理由"></textarea><button id="checkDelay" class="primary">完成后查看要点</button><div id="delayResult"></div>`);$('#checkDelay').onclick=()=>{const text=$('#delayAnswer').value.trim();if(!text){toast('先写下你的想法。');return;}$('#delayAnswer').disabled=true;$('#checkDelay').disabled=true;$('#delayResult').innerHTML=`<div class="notice">${E(q.answer)}</div><p class="smallnote">对照原来的独立尝试，解释是否包含关键关系？这是自检证据。</p><button id="delayYes">原尝试已包含要点</button> <button id="delayNo">还需要再练</button>`;const done=passed=>{const at=Date.now(),eligible=!prior&&r.passedAt&&at-r.passedAt>=3*86400000;if(!prior)r.delay={at,text,passed,eligible,source:'新题延迟自检'};profile().history.push({at,id,delay:true,passed,eligible,source:prior?'重复练习自检':eligible?'延迟新题自检':'即时新题自检'});save();closeModal();toast(eligible?'已保存延迟复查证据。':'已保存新题自检记录；未满3天时不作为延迟通过证据。');};$('#delayYes').onclick=()=>done(true);$('#delayNo').onclick=()=>done(false);};}
function profilesModal(){modalMode='profiles';showModal('每个孩子，都有自己的地图',`<p>免登录记录，保存在当前浏览器。同一设备可建多个档案；换设备请先导出，再导入。</p>${state.profiles.map(p=>`<div class="profileitem ${state.active===p.id?'active':''}"><div><b>${E(p.name)}</b><small class="smallnote">　${Object.keys(p.records).length}个已浏览或开始的节点</small></div><button data-switch="${E(p.id)}">${state.active===p.id?'当前档案':'切换'}</button></div>`).join('')}<form id="addProfile" class="formrow"><input id="newName" maxlength="40" placeholder="新档案名字，例如：姐姐" required><button type="submit">创建档案</button></form><form id="renameProfile" class="formrow"><input id="renameName" maxlength="40" value="${E(profile().name)}" aria-label="当前档案新名称" required><button type="submit">重命名当前档案</button></form><div class="backup"><h3>备份与迁移</h3><p class="smallnote">导出包含本设备所有档案。导入时会先校验并展示预览，默认合并，不覆盖现有档案。</p><button id="exportBackup">导出全部档案</button><button id="importBackup">导入备份</button><input id="backupFile" type="file" accept="application/json,.json" hidden></div>`);$$('[data-switch]').forEach(b=>b.onclick=()=>{state.active=b.dataset.switch;save();closeModal();toast('已切换学习档案。');});$('#addProfile').onsubmit=e=>{e.preventDefault();const name=$('#newName').value.trim();if(!name)return;if(state.profiles.length>=30){toast('最多30个档案，请先管理已有档案。');return;}const p={id:uid(),name,records:{},history:[]};state.profiles.push(p);state.active=p.id;save();closeModal();toast('新档案已创建，地图从未检查状态开始。');};$('#renameProfile').onsubmit=e=>{e.preventDefault();const name=$('#renameName').value.trim();if(!name)return;profile().name=name;save();closeModal();};$('#exportBackup').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='math-growth-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('#importBackup').onclick=()=>$('#backupFile').click();$('#backupFile').onchange=importBackup;}
async function importBackup(e){const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024){toast('备份文件过大，请使用本网站导出的JSON。');return;}try{const incoming=JSON.parse(await file.text());if(!validState(incoming))throw Error('schema');const ps=incoming.profiles;if(state.profiles.length+ps.length>30){toast('合并后超过30个档案，无法导入。');return;}showModal('确认导入的档案',`<p>找到${ps.length}个档案。将作为新档案添加；原有记录会保留。</p>${ps.map(p=>`<div class="record">${E(p.name)}<small>${Object.keys(p.records).length}个节点 · ${p.history.length}条记录</small></div>`).join('')}<button id="confirmImport" class="primary">添加这些档案</button>`);$('#confirmImport').onclick=()=>{ps.forEach(p=>state.profiles.push({...p,id:uid(),name:p.name+'（导入）'}));save();closeModal();toast('导入完成。可在档案菜单切换。');};}catch(err){toast('无法读取备份：请使用本站导出的完整JSON文件。');}}
function aboutModal(){showModal('图谱怎样使用，依据从哪里来',`<h3>三个层级，同时看见</h3><p>年级层：一至六年级，细分上下学期。知识依赖层：只在明确目标任务下讨论必要条件。能力层：理解应用、变式识别、迁移推理。</p><h3>范围与当前完成度</h3><p>当前${D.nodes.length}个主要知识节点、${D.edges.length}条建模关系，覆盖五板块和十二学期层。另将综合与实践作为跨板块任务组织。此为知识结构初版，尚非经过教材逐页审校的穷尽目录。</p><p>已配${Object.keys(D.banks).length}个核心节点的三阶诊断，共${Object.values(D.banks).reduce((s,b)=>s+b.tiers.flat().length,0)}项首轮任务和${Object.keys(D.banks).length}项新题复查。其余节点明确标注“训练待补充”。</p><h3>教材定位</h3><p>核对目标是北师大版2024起新版；当前节点年级与学期均为参考位置，尚未完成新版12册逐项核验，不提供未经核实的页码。</p><h3>每条箭头的含义</h3><p>实线：限定任务中的必要依赖；虚线：可能促进理解；点线：一般关联或待验证假设。每条线可在详情里查看任务和理由。目前属于建模判断，待实际教学验证；不能把一个错误反推成整条链未掌握。</p><h3>能力与学习证据</h3><p>能力候选关联不构成必经路径。分类与归纳不作为全部抽象、推理或迁移的必要前提。地图颜色表示连续通过的三阶任务；客观题判定和开放题自检分别留痕。开放题没有自动语义评分，因此阶梯结果属于学习自检线索。</p><h3>资料来源</h3>${D.sources.map(s=>`<div class="source"><a href="${E(s.url)}" target="_blank" rel="noreferrer">${E(s.title)} ↗</a><p>${E(s.note)}</p></div>`).join('')}<p class="smallnote">网站解释、连线理由与任务为独立编写，不是出版社的官方依赖图。当前设备数据可通过档案菜单导出。</p>`);}
fetch('data.json').then(r=>{if(!r.ok)throw Error('load');return r.json();}).then(d=>{D=d;init();}).catch(e=>{$('#loading').textContent='地图未能加载，请刷新重试。';console.error(e);});
function feedbackModal(id,t){const tr=tierRecord(id,t),qs=taskSet(id,t);const missing=qs.map((q,i)=>({q,a:tr.answers[i],i})).filter(x=>!taskIndependent(x.q,x.a));showModal(node(id).name+' · 本阶诊断记录',`<p>本次记录按任务分维度展示。某项受阻只提示需要检查，不直接推断前置知识全部缺失。</p>${qs.map((q,i)=>{const a=tr.answers[i];return `<div class="record"><b>${E(q.dim)}</b><small>${taskIndependent(q,a)?'独立完成'+(!q.expected?'（开放题自检）':'（数值判定）'):a?.hint?'提示后尝试，待新题独立检查':a?.afterReview?'看要点后修改，待新题检查':a?.revealed?'已检查，仍需补充或修正':'尚未检查'} · ${E(D.capnames[q.cap])}</small></div>`;}).join('')}<div class="notice"><b>N＋1 · 下一步建议</b><br>${missing.length?'先选“'+E(missing[0].q.dim)+'”这个小环节，重读条件或换一种表示；补学后再做新的独立任务。':t<2?'本阶已自检通过，可以尝试'+roman[t+2]+'阶：'+E(D.tiers[t+1])+'。':'三阶已完成自检。保留证据，隔3天再用新题检查；也可探索跨板块应用。'}</div><div class="actions"><button id="feedbackLesson">针对这个节点补学</button><button id="feedbackContinue" class="primary">${missing.length?'回到当前阶梯':'继续下一步'}</button></div>`);$('#feedbackLesson').onclick=()=>lessonModal(id,t);$('#feedbackContinue').onclick=()=>openTraining(id,missing.length?t:Math.min(t+1,2));}
function lessonModal(id,t){const n=node(id);const title=n.name;let diagram='',explain='',example='',mistake='';if(title==='乘法分配律'){diagram='<svg viewBox="0 0 360 180" role="img" aria-label="长方形分成宽相同的两块，分别表示5乘8与5乘2"><rect x="45" y="35" width="210" height="105" fill="#dae9f4" stroke="#447c9f"/><rect x="255" y="35" width="55" height="105" fill="#aecbdf" stroke="#447c9f"/><path d="M255 35V140" stroke="#285879" stroke-dasharray="5 4"/><text x="142" y="95" text-anchor="middle">5 × 8</text><text x="282" y="95" text-anchor="middle">5 × 2</text><text x="22" y="93">5</text><text x="135" y="24">8</text><text x="277" y="24">2</text><text x="105" y="170">同一块面积，两种算法</text></svg>';explain='宽相同，长可以拆成两段。整体算和分块算覆盖的是同一块面，所以面积相等。';example='5×(8＋2)=5×8＋5×2=50。逆着看，两个部分有共同因数5，也可以先合成长10的整体。';mistake='每一部分都要乘共同因数；不能把连乘中的两个因数直接相加。';}
else if(title==='列方程解决问题'){diagram='<svg viewBox="0 0 360 140" role="img" aria-label="三段未知量x再加6等于30"><rect x="25" y="35" width="80" height="40" fill="#dae9f4" stroke="#447c9f"/><rect x="105" y="35" width="80" height="40" fill="#dae9f4" stroke="#447c9f"/><rect x="185" y="35" width="80" height="40" fill="#dae9f4" stroke="#447c9f"/><rect x="265" y="35" width="45" height="40" fill="#afcde0" stroke="#447c9f"/><text x="60" y="61">x</text><text x="140" y="61">x</text><text x="220" y="61">x</text><text x="282" y="61">6</text><text x="105" y="111">3个x ＋ 6 ＝ 30</text></svg>';explain='未知量也是一个可以表示、比较和运算的量。先用图或文字找“哪两部分相等”，再写等式。';example='3x＋6=30，两边同时减6得3x=24，再同除以3得x=8。代回3×8＋6=30，检验通过。';mistake='“3倍再多6”是3x＋6；3(x＋6)却把多的6重复了3遍。';}
else if(title==='三角形面积'){diagram='<svg viewBox="0 0 360 180" role="img" aria-label="两个全等三角形拼成平行四边形，虚线标出垂直高"><path d="M30 140L100 35L315 35L245 140Z" fill="#dae9f4" stroke="#447c9f"/><path d="M30 140L315 35L245 140Z" fill="#9dbfd7" stroke="#447c9f"/><path d="M100 35V140" stroke="#285879" stroke-dasharray="5 4"/><path d="M100 130H110V140" fill="none" stroke="#285879"/><text x="100" y="163">底 b</text><text x="108" y="90">对应高 h</text></svg>';explain='把一个三角形复制一份，两个全等图形能拼成平行四边形。原三角形面积是拼后图形的一半。';example='底8、高6的三角形，面积8×6÷2=24。求高时可先把24乘2，恢复底高乘积48，再除以8。';mistake='高要与所选底垂直，可能落在底所在直线的延长线上；斜边不能随意当作高。';}
else if(title==='面积单位换算'){diagram='<div style="display:grid;grid-template-columns:repeat(10,1fr);width:200px;aspect-ratio:1;margin:20px auto;border:2px solid #447c9f">'+Array.from({length:100},()=>'<span style="border:.5px solid #8caec6;background:#e3eff7"></span>').join('')+'</div><p style="text-align:center">每边10厘米 → 10行 × 10格 = 100平方厘米</p>';explain='边长1分米的正方形，每条边是10厘米。小格不是只有一排，而是10行、每行10格。';example='1平方分米=100平方厘米。3平方米=300平方分米=30000平方厘米；先识别量的维度，再决定进率。';mistake='同一面积换成小单位，数值变大，面积本身不变；长度的进率不能直接当成面积的进率。';}
else if(title==='平均数的意义'){diagram='<svg viewBox="0 0 360 180" role="img" aria-label="三根条形表示2、4、6，虚线在平均数4的高度"><path d="M30 145H320" stroke="#6e93ac"/><rect x="60" y="105" width="45" height="40" fill="#b1ccdf"/><rect x="145" y="65" width="45" height="80" fill="#8bb0cd"/><rect x="230" y="25" width="45" height="120" fill="#4f83a8"/><path d="M30 65H320" stroke="#285879" stroke-dasharray="5 4"/><text x="77" y="164">2</text><text x="162" y="164">4</text><text x="247" y="164">6</text><text x="290" y="56">均分4</text></svg>';explain='把多的移给少的，直到各份相同；总量不变。这个“假想均分后的数”描述整体水平，不代表每个人都恰好等于它。';example='2、4、6的总量12，分成3份，平均4。合并不同人数的组时，先恢复各组总量，再除以合计人数。';mistake='不能不看各组人数，就把两个组的平均数直接取平均；缺失数据也不能随意记成0。';}
else if(title==='三角形分类'){diagram='<svg viewBox="0 0 360 170" role="img" aria-label="三角形集合包含等腰三角形，等腰又包含等边"><rect x="15" y="15" width="330" height="140" rx="12" fill="#f1f6fa" stroke="#aac4d6"/><rect x="90" y="48" width="230" height="90" rx="12" fill="#dceaf4" stroke="#6e9abb"/><rect x="195" y="80" width="108" height="45" rx="10" fill="#a8c6db" stroke="#447c9f"/><text x="30" y="39">三角形</text><text x="110" y="72">等腰三角形</text><text x="204" y="108">等边三角形</text></svg>';explain='先说分类标准：按边的相等关系，或按角的大小。两个标准可以交叉；同一个三角形能既是等腰又是直角。';example='等边三角形有三条边相等，自然满足“至少两边相等”，所以是特殊的等腰三角形。等腰顶角40度时，两底角各70度。';mistake='等腰并不一定是锐角；40、40、100度就是一个反例。图形朝向改变，也不会改变边角性质。';}
if(!explain){const first=taskSet(id,t)[0];explain=n.desc;example=first.prompt+' 参考：'+first.answer;mistake='先明确整体、单位、对应关系与不变条件；一道题受阻不直接说明全部基础缺失。';diagram='<div class="notice">先用实物或草图 → 说出数量关系 → 写成算式 → 回到原情境检查</div>';}
showModal(title+' · 换一种表示补学',`<div style="max-width:430px;margin:auto">${diagram}</div><h3>先抓住这个关系</h3><p>${explain}</p><div class="notice">${example}</div><h3>容易混淆的地方</h3><p>${mistake}</p><p class="smallnote">这里的图示是一个入口，也可以先用实物、语言或算式。补学不直接增加通过阶梯。</p><div class="actions"><button id="backToTasks">回到任务</button><button id="lessonNew" class="primary">换题独立检查</button></div>`);$('#backToTasks').onclick=()=>openTraining(id,t);$('#lessonNew').onclick=()=>{const r=rec(id),tr=tierRecord(id,t);if(tr.round===1){openTraining(id,t);toast('已在第二组任务中；先保留自己的新尝试。');return;}r.archive??=[];r.archive.push({t,record:JSON.parse(JSON.stringify(tr)),at:Date.now()});r.tiers[t]={answers:{},round:1,passed:false};save();openTraining(id,t);};}
